code.js:
const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const list = document.getElementById("chores");
const filter = document.querySelector("[data-hook=filter]");
const status = document.getElementById("status");
let state;
let today = "";
let weekday = 0;
const fold = (text) => text.trim().split(" ").filter(Boolean).join(" ");
// The next day on or after today that falls on the chore's weekday.
const nextOn = (every) => {
  const [y, m, d] = today.split("-").map(Number);
  const at = new Date(Date.UTC(y, m - 1, d + ((every - weekday + 7) % 7)));
  return at.toISOString().slice(0, 10);
};
const dueOf = (chore) => (typeof chore.every === "number" ? nextOn(chore.every) : today);
const render = () => {
  const people = [...new Set(state.data.chores.map((chore) => fold(chore.who)))].sort();
  const chosen = filter.value;
  filter.replaceChildren(
    new Option("Everyone", ""),
    ...people.map((who) => new Option(who === "Me" ? "Only mine" : who, who)),
  );
  filter.value = people.includes(chosen) ? chosen : "";
  const shown = state.data.chores.filter((chore) => !filter.value || fold(chore.who) === filter.value);
  list.replaceChildren(...shown.map((chore) => {
    const item = document.createElement("li");
    item.dataset.hook = "item";
    const due = dueOf(chore);
    const done = (chore.doneOn ?? []).includes(due);
    const box = document.createElement("input");
    box.type = "checkbox";
    box.id = "done-" + chore.id;
    box.checked = done;
    box.addEventListener("change", () => {
      const doneOn = box.checked
        ? [...(chore.doneOn ?? []), due]
        : (chore.doneOn ?? []).filter((day) => day !== due);
      save([{ op: "replace", collection: "chores", id: chore.id, revisionCount: state.revisions.chores[chore.id], fields: { doneOn } }], box.checked ? "Done." : "Not done yet.");
    });
    const label = document.createElement("label");
    label.htmlFor = box.id;
    label.textContent = chore.name;
    if (done) label.className = "done";
    const who = document.createElement("span");
    who.dataset.hook = "category";
    who.textContent = chore.who;
    const when = document.createElement("time");
    when.dateTime = due;
    when.textContent = typeof chore.every === "number" ? "every " + DAYS[chore.every] + ", next " + due : "today";
    const remove = document.createElement("button");
    remove.type = "button";
    remove.dataset.hook = "item-remove";
    remove.textContent = "Remove " + chore.name;
    remove.addEventListener("click", () =>
      save([{ op: "remove", collection: "chores", id: chore.id, revisionCount: state.revisions.chores[chore.id] }], "Removed."),
    );
    item.append(box, label, who, when, remove);
    return item;
  }));
};
const load = () => tessera.call("data.read").then((read) => { state = read; render(); });
const save = (operations, said) =>
  tessera.call("data.patch", { operations }).then(load).then(
    () => { status.textContent = said; },
    () => { status.textContent = "That wasn't saved. Try again."; return load(); },
  );
filter.addEventListener("change", render);
tessera.call("clock.now").then((now) => {
  today = now.date;
  const [y, m, d] = today.split("-").map(Number);
  weekday = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
  return load();
});
document.querySelector("[data-hook=item-add]").addEventListener("click", () => {
  const name = document.querySelector("[data-hook=item-name]").value.trim();
  const who = fold(document.querySelector("[data-hook=item-category]").value);
  if (!name || !who) { status.textContent = "Write the chore and who does it."; return; }
  document.querySelector("[data-hook=item-name]").value = "";
  save([{ op: "add", collection: "chores", record: { name, who } }], name + " is on the board.");
});
